    """Parse a family-compaction marker.

    Forms accepted:

    * ``{"v": 1, "u": u, "m": [abs paths]}`` -- staging/streaming;
    * the same plus ``"p": [ints]`` -- per-member promotion in force;
    * the same with ``"h": [ints]`` (without ``p``) -- heads switched,
      only basis-link convergence and cleanup remaining.
    """
    try:
        marker = json.loads(raw.decode("ascii"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CheckpointError("family compaction marker is corrupt") from exc
    if not isinstance(marker, dict):
        raise CheckpointError("family compaction marker is corrupt")
    if set(marker) not in (
        {"v", "u", "m"},
        {"v", "u", "m", "p"},
        {"v", "u", "m", "h"},
