import os, tempfile, threading
from sequence_engine import checkpoint as cp
from sequence_engine._selftest import _fresh_stack, _SEG1, _SEG2, _total, _LR, _ADAM_LR
from sequence_engine import Tensor

def trained(path, steps):
    os.mkdir(path)
    s,_=_fresh_stack(); s.save(path); hh=None
    for i in range(steps):
        o,hh=s.forward(Tensor(_SEG1 if i%2==0 else _SEG2),hh); s.backward(_total(o))
        if i%2: s.adam_step(_ADAM_LR)
        else: s.update(_LR)
        s.save(path)
    return s

with tempfile.TemporaryDirectory() as root:
    main=os.path.join(root,"main"); b1=os.path.join(root,"b1"); b2=os.path.join(root,"b2")
    trained(main,6)
    cp.fork_chain(main,b1,up_to=4)
    cp.fork_chain(main,b2,up_to=3)
    dirs=[main,b1,b2]
    errors=[]; stop=False

    def appender(d):
        try:
            for _ in range(80):
                doc=cp.load_chain(d)
                cp.save_chain(doc,d)  # empty delta
        except BaseException as e:
            errors.append(("app",d,e))

    def reader(d):
        try:
            while not stop:
                cp.build_bytes(cp.load_chain(d))
        except BaseException as e:
            errors.append(("read",d,e))

    def single_compactor(d):
        try:
            for _ in range(30):
                cp.compact_chain(d)
        except BaseException as e:
            errors.append(("compact",d,e))

    threads=[]
    for d in dirs:
        threads.append(threading.Thread(target=appender,args=(d,)))
        threads.append(threading.Thread(target=reader,args=(d,)))
    for d in (b1,b2):
        threads.append(threading.Thread(target=single_compactor,args=(d,)))
    for t in threads: t.start()
    for _ in range(40):
        try:
            cp.compact_family(dirs)
        except BaseException as e:
            errors.append(("family",None,e))
    stop=True
